mapper.sql:
FROM rental_order ro LEFT JOIN xianyu_order xo ON xo.id = ro.channel_order_id AND xo.tenant_id = ro.tenant_id AND xo.deleted = b'0' WHERE ro.tenant_id = #{tenantId} AND ro.deleted = b'0'
AND ro.status = 'PENDING_ALLOCATION' AND ro.preparation_status = 'READY' AND EXISTS (SELECT 1 FROM rental_order_item i WHERE i.rental_order_id = ro.id AND i.tenant_id = ro.tenant_id AND i.deleted = b'0' AND i.quantity > (SELECT COUNT(*) FROM rental_device_assignment a WHERE a.rental_order_item_id = i.id AND a.tenant_id = ro.tenant_id AND a.deleted = b'0' AND a.status IN ('ASSIGNED', 'DISPATCHED', 'DISPATCHED_PENDING_PLAN')))
AND () = #{queue}

mapper.select:
SELECT ro.id, ro.order_no, ro.channel_order_id, ro.source_type, ro.source_order_id, ro.status, ro.billable_start_date, ro.billable_end_date, ro.occupy_start_date, ro.occupy_end_date_exclusive, xo.external_order_id AS external_order_no, xo.goods_title, xo.receiver_name, xo.receiver_mobile, xo.receiver_address, () AS shipping_status
AND ro.id < #{beforeId}
AND (LOWER(ro.order_no) LIKE #{keyword} ESCAPE '!' OR LOWER(xo.external_order_id) LIKE #{keyword} ESCAPE '!' OR LOWER(xo.goods_title) LIKE #{keyword} ESCAPE '!' OR LOWER(xo.receiver_name) LIKE #{keyword} ESCAPE '!' OR LOWER(xo.receiver_mobile) LIKE #{keyword} ESCAPE '!' OR LOWER(xo.receiver_address) LIKE #{keyword} ESCAPE '!' OR EXISTS (SELECT 1 FROM rental_order_item i WHERE i.rental_order_id = ro.id AND i.tenant_id = ro.tenant_id AND i.deleted = b'0' AND LOWER(i.equipment_model_code) LIKE #{keyword} ESCAPE '!') OR EXISTS (SELECT 1 FROM rental_order_delivery d WHERE d.rental_order_id = ro.id AND d.tenant_id = ro.tenant_id AND d.deleted = b'0'))
ORDER BY ro.id DESC LIMIT #{offset}, #{limit}
